-- Sales Call Compliance: PostgreSQL 17 schema. Generated by docs/design/tools/gen_model.py.
-- Applied as migration 0001. RLS is enabled with no policies: only the API's database role reads (ADR-0003).
BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TYPE user_role AS ENUM ('qa_reviewer', 'agent', 'manager');
CREATE TYPE call_status AS ENUM ('uploaded', 'transcribing', 'transcribed', 'scoring', 'scored', 'failed');
CREATE TYPE speaker_channel AS ENUM ('agent', 'customer');
CREATE TYPE rubric_item_type AS ENUM ('mandatory', 'prohibited', 'quality');
CREATE TYPE finding_status AS ENUM ('met', 'missed', 'partial', 'breach', 'clear', 'not_applicable');
CREATE TYPE finding_source AS ENUM ('llm', 'rule', 'reviewer');
CREATE TYPE review_status AS ENUM ('not_required', 'pending', 'done');
CREATE TYPE review_decision AS ENUM ('agree', 'disagree');
CREATE TYPE model_kind AS ENUM ('chat', 'stt', 'tts');
CREATE TYPE model_call_status AS ENUM ('ok', 'error', 'refused');

-- Serves US-01-001, US-01-008
CREATE TABLE teams (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chk_teams_name_not_blank CHECK (length(btrim(name)) > 0)
);
COMMENT ON TABLE teams IS 'Sales teams calls are grouped by, for upload metadata and the manager dashboard.';
COMMENT ON COLUMN teams.id IS 'Identifier of the team';
COMMENT ON COLUMN teams.name IS 'Team name as managers know it';
COMMENT ON COLUMN teams.created_at IS 'When the row was created';
CREATE UNIQUE INDEX uq_teams_name ON teams (name);
ALTER TABLE teams ENABLE ROW LEVEL SECURITY;

-- Serves US-01-001, US-01-008
CREATE TABLE products (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chk_products_name_not_blank CHECK (length(btrim(name)) > 0)
);
COMMENT ON TABLE products IS 'Products a call is about, for upload metadata and the dashboard.';
COMMENT ON COLUMN products.id IS 'Identifier of the product';
COMMENT ON COLUMN products.name IS 'Product name';
COMMENT ON COLUMN products.created_at IS 'When the row was created';
CREATE UNIQUE INDEX uq_products_name ON products (name);
ALTER TABLE products ENABLE ROW LEVEL SECURITY;

-- Serves US-01-001, US-00-001, US-00-002
CREATE TABLE agents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  team_id uuid NOT NULL REFERENCES teams (id) ON DELETE RESTRICT,
  name text NOT NULL,
  external_code text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chk_agents_name_not_blank CHECK (length(btrim(name)) > 0)
);
COMMENT ON TABLE agents IS 'Sales agents whose calls are scored; separate from login profiles because agents can be scored before they have an account.';
COMMENT ON COLUMN agents.id IS 'Identifier of the agent';
COMMENT ON COLUMN agents.team_id IS 'Team the agent belongs to';
COMMENT ON COLUMN agents.name IS 'Agent display name';
COMMENT ON COLUMN agents.external_code IS 'Agent code from the distributor''s HR system';
COMMENT ON COLUMN agents.created_at IS 'When the row was created';
CREATE INDEX idx_agents_team_id ON agents (team_id);
CREATE UNIQUE INDEX uq_agents_external_code ON agents (external_code);
ALTER TABLE agents ENABLE ROW LEVEL SECURITY;

-- Serves US-00-003, US-00-001
CREATE TABLE profiles (
  id uuid PRIMARY KEY,
  email text NOT NULL,
  display_name text NOT NULL,
  role user_role NOT NULL,
  agent_id uuid REFERENCES agents (id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chk_profiles_agent_link CHECK ((role = 'agent') = (agent_id IS NOT NULL))
);
COMMENT ON TABLE profiles IS 'The role and agent link of each Supabase Auth user; the API reads it on every request.';
COMMENT ON COLUMN profiles.id IS 'The Supabase Auth user id (JWT sub)';
COMMENT ON COLUMN profiles.email IS 'Sign-in email, copied from Auth for display';
COMMENT ON COLUMN profiles.display_name IS 'Name shown in the UI';
COMMENT ON COLUMN profiles.role IS 'The user''s single role';
COMMENT ON COLUMN profiles.agent_id IS 'Agent record of a user whose role is agent';
COMMENT ON COLUMN profiles.created_at IS 'When the row was created';
COMMENT ON COLUMN profiles.updated_at IS 'When the row last changed';
CREATE UNIQUE INDEX uq_profiles_email ON profiles (lower(email));
CREATE UNIQUE INDEX uq_profiles_agent_id ON profiles (agent_id) WHERE agent_id IS NOT NULL;
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;

-- Serves US-01-003, US-01-004
CREATE TABLE rubrics (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  version integer NOT NULL,
  name text NOT NULL,
  items jsonb NOT NULL,
  is_active boolean NOT NULL DEFAULT false,
  created_by uuid REFERENCES profiles (id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chk_rubrics_items_array CHECK (jsonb_typeof(items) = 'array' AND jsonb_array_length(items) > 0)
);
COMMENT ON TABLE rubrics IS 'Versioned rubrics; exactly one active version scores new calls, and old scores keep the version they used (Q-006).';
COMMENT ON COLUMN rubrics.id IS 'Identifier of the rubric version';
COMMENT ON COLUMN rubrics.version IS 'Monotonic version number';
COMMENT ON COLUMN rubrics.name IS 'Human name of the rubric';
COMMENT ON COLUMN rubrics.items IS 'Rubric items: key, type, label, description, examples';
COMMENT ON COLUMN rubrics.is_active IS 'Whether this version scores new calls';
COMMENT ON COLUMN rubrics.created_by IS 'Manager who saved the version; null for the seeded default';
COMMENT ON COLUMN rubrics.created_at IS 'When the row was created';
CREATE UNIQUE INDEX uq_rubrics_version ON rubrics (version);
CREATE UNIQUE INDEX uq_rubrics_active ON rubrics (is_active) WHERE is_active;
CREATE INDEX idx_rubrics_created_by ON rubrics (created_by);
ALTER TABLE rubrics ENABLE ROW LEVEL SECURITY;

-- Serves US-01-001, US-01-002, US-01-005, US-00-001, US-01-008, US-02-003
CREATE TABLE calls (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  agent_id uuid NOT NULL REFERENCES agents (id) ON DELETE RESTRICT,
  team_id uuid NOT NULL REFERENCES teams (id) ON DELETE RESTRICT,
  product_id uuid NOT NULL REFERENCES products (id) ON DELETE RESTRICT,
  call_date date NOT NULL,
  batch_id uuid NOT NULL,
  uploaded_by uuid NOT NULL REFERENCES profiles (id) ON DELETE RESTRICT,
  original_filename text NOT NULL,
  mime_type text NOT NULL,
  size_bytes bigint NOT NULL,
  storage_path text,
  duration_ms integer,
  status call_status NOT NULL DEFAULT 'uploaded',
  error text,
  retention_until date NOT NULL,
  audio_purged_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chk_calls_mime_type CHECK (mime_type IN ('audio/wav', 'audio/mpeg')),
  CONSTRAINT chk_calls_size_bytes CHECK (size_bytes > 0 AND size_bytes <= 52428800),
  CONSTRAINT chk_calls_failed_has_error CHECK ((status = 'failed') = (error IS NOT NULL)),
  CONSTRAINT chk_calls_purged_has_no_path CHECK (audio_purged_at IS NULL OR storage_path IS NULL)
);
COMMENT ON TABLE calls IS 'One uploaded recording and its pipeline state.';
COMMENT ON COLUMN calls.id IS 'Identifier of the call';
COMMENT ON COLUMN calls.agent_id IS 'Agent on the left channel';
COMMENT ON COLUMN calls.team_id IS 'Team at the time of the call';
COMMENT ON COLUMN calls.product_id IS 'Product discussed';
COMMENT ON COLUMN calls.call_date IS 'Date the call took place';
COMMENT ON COLUMN calls.batch_id IS 'Upload batch shared by files uploaded together';
COMMENT ON COLUMN calls.uploaded_by IS 'QA reviewer or manager who uploaded';
COMMENT ON COLUMN calls.original_filename IS 'File name as uploaded';
COMMENT ON COLUMN calls.mime_type IS 'audio/wav or audio/mpeg';
COMMENT ON COLUMN calls.size_bytes IS 'File size';
COMMENT ON COLUMN calls.storage_path IS 'Object path in the private recordings bucket; null once purged';
COMMENT ON COLUMN calls.duration_ms IS 'Recording length, known after decoding';
COMMENT ON COLUMN calls.status IS 'Pipeline state';
COMMENT ON COLUMN calls.error IS 'Reason the call failed, safe to show users';
COMMENT ON COLUMN calls.retention_until IS 'Date after which the audio is purged';
COMMENT ON COLUMN calls.audio_purged_at IS 'When the audio was deleted';
COMMENT ON COLUMN calls.created_at IS 'When the row was created';
COMMENT ON COLUMN calls.updated_at IS 'When the row last changed';
CREATE INDEX idx_calls_agent_id_created_at ON calls (agent_id, created_at DESC);
CREATE INDEX idx_calls_team_id_call_date ON calls (team_id, call_date);
CREATE INDEX idx_calls_product_id_call_date ON calls (product_id, call_date);
CREATE INDEX idx_calls_status_created_at ON calls (status, created_at DESC);
CREATE INDEX idx_calls_batch_id ON calls (batch_id);
CREATE UNIQUE INDEX uq_calls_storage_path ON calls (storage_path) WHERE storage_path IS NOT NULL;
CREATE INDEX idx_calls_uploaded_by ON calls (uploaded_by);
CREATE INDEX idx_calls_retention_until ON calls (retention_until) WHERE audio_purged_at IS NULL;
ALTER TABLE calls ENABLE ROW LEVEL SECURITY;

-- Serves US-01-002, US-01-003, US-01-006
CREATE TABLE transcript_segments (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  call_id uuid NOT NULL REFERENCES calls (id) ON DELETE CASCADE,
  seq integer NOT NULL,
  channel speaker_channel NOT NULL,
  start_ms integer NOT NULL,
  end_ms integer NOT NULL,
  text text NOT NULL,
  language text,
  avg_logprob real,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chk_transcript_segments_times CHECK (start_ms >= 0 AND end_ms >= start_ms)
);
COMMENT ON TABLE transcript_segments IS 'Timestamped text per channel; the source of every finding''s quote and time (tenet 2).';
COMMENT ON COLUMN transcript_segments.id IS 'Row id';
COMMENT ON COLUMN transcript_segments.call_id IS 'Call the segment belongs to';
COMMENT ON COLUMN transcript_segments.seq IS 'Order of the segment in the call, both channels merged by start time';
COMMENT ON COLUMN transcript_segments.channel IS 'Agent or customer';
COMMENT ON COLUMN transcript_segments.start_ms IS 'Start in call time, milliseconds';
COMMENT ON COLUMN transcript_segments.end_ms IS 'End in call time, milliseconds';
COMMENT ON COLUMN transcript_segments.text IS 'Transcribed words';
COMMENT ON COLUMN transcript_segments.language IS 'Language Whisper detected for the chunk';
COMMENT ON COLUMN transcript_segments.avg_logprob IS 'Whisper confidence for the segment';
COMMENT ON COLUMN transcript_segments.created_at IS 'When the row was created';
CREATE UNIQUE INDEX uq_transcript_segments_call_id_seq ON transcript_segments (call_id, seq);
ALTER TABLE transcript_segments ENABLE ROW LEVEL SECURITY;

-- Serves US-02-001, US-01-003
CREATE TABLE model_calls (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  provider text NOT NULL,
  model text NOT NULL,
  kind model_kind NOT NULL,
  purpose text NOT NULL,
  call_id uuid REFERENCES calls (id) ON DELETE SET NULL,
  status model_call_status NOT NULL,
  input_tokens integer NOT NULL DEFAULT 0,
  cached_tokens integer NOT NULL DEFAULT 0,
  output_tokens integer NOT NULL DEFAULT 0,
  audio_seconds numeric(10,2) NOT NULL DEFAULT 0,
  characters integer NOT NULL DEFAULT 0,
  cost_usd numeric(12,6) NOT NULL DEFAULT 0,
  latency_ms integer NOT NULL DEFAULT 0,
  error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chk_model_calls_nonnegative CHECK (input_tokens >= 0 AND cached_tokens >= 0 AND output_tokens >= 0 AND audio_seconds >= 0 AND characters >= 0 AND cost_usd >= 0),
  CONSTRAINT chk_model_calls_output_cap CHECK (output_tokens <= 1000)
);
COMMENT ON TABLE model_calls IS 'One row per gateway call: the cost log and the budget total.';
COMMENT ON COLUMN model_calls.id IS 'Identifier of the model call';
COMMENT ON COLUMN model_calls.provider IS 'groq, openrouter or gemini';
COMMENT ON COLUMN model_calls.model IS 'Model id sent to the provider';
COMMENT ON COLUMN model_calls.kind IS 'chat, stt or tts';
COMMENT ON COLUMN model_calls.purpose IS 'What the call was for: score, transcribe, seed_tts, eval';
COMMENT ON COLUMN model_calls.call_id IS 'Call the model call served, if any';
COMMENT ON COLUMN model_calls.status IS 'ok, error or refused';
COMMENT ON COLUMN model_calls.input_tokens IS 'Prompt tokens billed';
COMMENT ON COLUMN model_calls.cached_tokens IS 'Prompt tokens served from cache at half price';
COMMENT ON COLUMN model_calls.output_tokens IS 'Completion tokens, reasoning included';
COMMENT ON COLUMN model_calls.audio_seconds IS 'Billed audio seconds for transcription';
COMMENT ON COLUMN model_calls.characters IS 'Characters voiced for TTS';
COMMENT ON COLUMN model_calls.cost_usd IS 'Cost of this call in US dollars';
COMMENT ON COLUMN model_calls.latency_ms IS 'Wall time of the request';
COMMENT ON COLUMN model_calls.error IS 'Provider or gateway error summary, no content';
COMMENT ON COLUMN model_calls.created_at IS 'When the row was created';
CREATE INDEX idx_model_calls_call_id ON model_calls (call_id);
CREATE INDEX idx_model_calls_created_at ON model_calls (created_at);
ALTER TABLE model_calls ENABLE ROW LEVEL SECURITY;

-- Serves US-01-003, US-01-005, US-01-006, US-00-001, US-00-002
CREATE TABLE scores (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  call_id uuid NOT NULL REFERENCES calls (id) ON DELETE CASCADE,
  rubric_id uuid NOT NULL REFERENCES rubrics (id) ON DELETE RESTRICT,
  model_call_id uuid REFERENCES model_calls (id) ON DELETE SET NULL,
  overall_score numeric(5,2),
  judge_status text NOT NULL,
  judge_error text,
  talk_ratio numeric(4,3) NOT NULL,
  coaching_notes jsonb NOT NULL DEFAULT '[]'::jsonb,
  needs_review boolean NOT NULL,
  review_status review_status NOT NULL,
  reviewed_by uuid REFERENCES profiles (id) ON DELETE RESTRICT,
  reviewed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chk_scores_talk_ratio CHECK (talk_ratio >= 0 AND talk_ratio <= 1),
  CONSTRAINT chk_scores_overall CHECK (overall_score IS NULL OR (overall_score >= 0 AND overall_score <= 100)),
  CONSTRAINT chk_scores_judge_status CHECK ((judge_status = 'ok' AND judge_error IS NULL AND overall_score IS NOT NULL) OR (judge_status = 'failed' AND judge_error IS NOT NULL AND overall_score IS NULL AND needs_review)),
  CONSTRAINT chk_scores_routing CHECK ((needs_review AND review_status <> 'not_required') OR (NOT needs_review AND review_status = 'not_required')),
  CONSTRAINT chk_scores_review_done CHECK ((review_status = 'done') = (reviewed_at IS NOT NULL AND reviewed_by IS NOT NULL)),
  CONSTRAINT chk_scores_notes_array CHECK (jsonb_typeof(coaching_notes) = 'array' AND jsonb_array_length(coaching_notes) <= 3)
);
COMMENT ON TABLE scores IS 'The current judgement of a call: talk ratio, coaching notes and QA routing. A rescore replaces it while review is not done.';
COMMENT ON COLUMN scores.id IS 'Identifier of the score';
COMMENT ON COLUMN scores.call_id IS 'Scored call; one current score each';
COMMENT ON COLUMN scores.rubric_id IS 'Rubric version used';
COMMENT ON COLUMN scores.model_call_id IS 'The judge call that produced it';
COMMENT ON COLUMN scores.overall_score IS 'Percent of applicable mandatory and quality items met, zero if any breach; null when the judge failed';
COMMENT ON COLUMN scores.judge_status IS 'ok when the judge produced valid findings, failed otherwise';
COMMENT ON COLUMN scores.judge_error IS 'Why the judge failed, safe to show reviewers';
COMMENT ON COLUMN scores.talk_ratio IS 'Agent speech time over total speech time';
COMMENT ON COLUMN scores.coaching_notes IS 'Up to three notes from the judge';
COMMENT ON COLUMN scores.needs_review IS 'Whether routing sent the call to QA';
COMMENT ON COLUMN scores.review_status IS 'not_required, pending or done';
COMMENT ON COLUMN scores.reviewed_by IS 'Reviewer who completed the review';
COMMENT ON COLUMN scores.reviewed_at IS 'When the review was completed';
COMMENT ON COLUMN scores.created_at IS 'When the row was created';
COMMENT ON COLUMN scores.updated_at IS 'When the row last changed';
CREATE UNIQUE INDEX uq_scores_call_id ON scores (call_id);
CREATE INDEX idx_scores_review_queue ON scores (created_at) WHERE review_status = 'pending';
CREATE INDEX idx_scores_rubric_id ON scores (rubric_id);
CREATE INDEX idx_scores_model_call_id ON scores (model_call_id);
CREATE INDEX idx_scores_reviewed_by ON scores (reviewed_by);
ALTER TABLE scores ENABLE ROW LEVEL SECURITY;

-- Serves US-01-003, US-01-005, US-01-006, US-01-007, US-00-002, US-02-002
CREATE TABLE findings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  score_id uuid NOT NULL REFERENCES scores (id) ON DELETE CASCADE,
  call_id uuid NOT NULL REFERENCES calls (id) ON DELETE CASCADE,
  item_key text NOT NULL,
  item_type rubric_item_type NOT NULL,
  status finding_status NOT NULL,
  source finding_source NOT NULL,
  quote text,
  segment_seq integer,
  start_ms integer,
  end_ms integer,
  channel speaker_channel,
  rationale text,
  grounded boolean NOT NULL DEFAULT true,
  created_by uuid REFERENCES profiles (id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chk_findings_times CHECK ((start_ms IS NULL AND end_ms IS NULL) OR (start_ms >= 0 AND end_ms >= start_ms)),
  CONSTRAINT chk_findings_reviewer_source CHECK ((source = 'reviewer') = (created_by IS NOT NULL)),
  CONSTRAINT chk_findings_status_fits_type CHECK ((item_type = 'prohibited' AND status IN ('breach', 'clear', 'not_applicable')) OR (item_type <> 'prohibited' AND status IN ('met', 'missed', 'partial', 'not_applicable')))
);
COMMENT ON TABLE findings IS 'One judgement on one rubric item for one call, with its evidence.';
COMMENT ON COLUMN findings.id IS 'Identifier of the finding';
COMMENT ON COLUMN findings.score_id IS 'Score the finding belongs to';
COMMENT ON COLUMN findings.call_id IS 'Call, copied from the score for direct reads';
COMMENT ON COLUMN findings.item_key IS 'Rubric item key, such as guaranteed_returns';
COMMENT ON COLUMN findings.item_type IS 'mandatory, prohibited or quality';
COMMENT ON COLUMN findings.status IS 'met, missed, partial, breach, clear or not_applicable';
COMMENT ON COLUMN findings.source IS 'llm, rule or reviewer';
COMMENT ON COLUMN findings.quote IS 'Words from the transcript that evidence the finding';
COMMENT ON COLUMN findings.segment_seq IS 'Transcript segment cited';
COMMENT ON COLUMN findings.start_ms IS 'Start of the evidence, copied from the segment';
COMMENT ON COLUMN findings.end_ms IS 'End of the evidence, copied from the segment';
COMMENT ON COLUMN findings.channel IS 'Who said the quoted words';
COMMENT ON COLUMN findings.rationale IS 'Short reason from the judge or reviewer';
COMMENT ON COLUMN findings.grounded IS 'Whether the quote matched the cited segment';
COMMENT ON COLUMN findings.created_by IS 'Reviewer who added a missed finding';
COMMENT ON COLUMN findings.created_at IS 'When the row was created';
CREATE INDEX idx_findings_score_id ON findings (score_id);
CREATE INDEX idx_findings_call_id ON findings (call_id);
CREATE INDEX idx_findings_item_key_source ON findings (item_key, source);
CREATE UNIQUE INDEX uq_findings_llm_item ON findings (score_id, item_key) WHERE source = 'llm';
CREATE INDEX idx_findings_created_by ON findings (created_by);
ALTER TABLE findings ENABLE ROW LEVEL SECURITY;

-- Serves US-01-006, US-01-007
CREATE TABLE finding_reviews (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  finding_id uuid NOT NULL REFERENCES findings (id) ON DELETE CASCADE,
  reviewer_id uuid NOT NULL REFERENCES profiles (id) ON DELETE RESTRICT,
  decision review_decision NOT NULL,
  note text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chk_finding_reviews_note_length CHECK (note IS NULL OR length(note) <= 2000)
);
COMMENT ON TABLE finding_reviews IS 'A QA reviewer''s agree or disagree on one finding.';
COMMENT ON COLUMN finding_reviews.id IS 'Identifier of the review';
COMMENT ON COLUMN finding_reviews.finding_id IS 'Finding decided on';
COMMENT ON COLUMN finding_reviews.reviewer_id IS 'Reviewer who decided';
COMMENT ON COLUMN finding_reviews.decision IS 'agree or disagree';
COMMENT ON COLUMN finding_reviews.note IS 'Optional reviewer note';
COMMENT ON COLUMN finding_reviews.created_at IS 'When the row was created';
COMMENT ON COLUMN finding_reviews.updated_at IS 'When the row last changed';
CREATE UNIQUE INDEX uq_finding_reviews_finding_id ON finding_reviews (finding_id);
CREATE INDEX idx_finding_reviews_reviewer_id ON finding_reviews (reviewer_id);
ALTER TABLE finding_reviews ENABLE ROW LEVEL SECURITY;

-- Serves US-02-003
CREATE TABLE audit_events (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  actor_id uuid REFERENCES profiles (id) ON DELETE RESTRICT,
  action text NOT NULL,
  call_id uuid REFERENCES calls (id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chk_audit_events_action CHECK (action IN ('audio_url_issued', 'call_uploaded', 'rubric_saved', 'review_completed', 'audio_purged', 'finding_decided', 'call_retried'))
);
COMMENT ON TABLE audit_events IS 'Who accessed which recording and when.';
COMMENT ON COLUMN audit_events.id IS 'Row id';
COMMENT ON COLUMN audit_events.actor_id IS 'User who acted; null for system jobs';
COMMENT ON COLUMN audit_events.action IS 'What happened, such as audio_url_issued';
COMMENT ON COLUMN audit_events.call_id IS 'Call acted on';
COMMENT ON COLUMN audit_events.created_at IS 'When the row was created';
CREATE INDEX idx_audit_events_call_id ON audit_events (call_id);
CREATE INDEX idx_audit_events_actor_id_created_at ON audit_events (actor_id, created_at);
ALTER TABLE audit_events ENABLE ROW LEVEL SECURITY;

COMMIT;
